const crypto = require('crypto');
const secret = $env.RAZORPAY_WEBHOOK_SECRET || '';
const raw = $input.item.json.rawBody ?? JSON.stringify($input.item.json.body ?? {});
const sent = String($input.item.json.headers?.['x-razorpay-signature'] || '');
const expected = secret ? crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex') : '';
const ok = Boolean(secret) && sent.length === expected.length && crypto.timingSafeEqual(Buffer.from(sent), Buffer.from(expected));
const p = $input.item.json.body?.payload?.payment?.entity ?? {};
return { json: { signatureValid: ok, paymentId: p.id || '', orderId: p.order_id || '', amount: Number(p.amount || 0) / 100, currency: p.currency || 'INR', contact: String(p.contact || '').replace(/[^0-9]/g, ''), email: p.email || '', method: p.method || '' } };

